python3 - <<'PY'
import urllib.request,json
urls=['https://registry.npmjs.org/-/v1/search?text=moca%20benchmark&size=10',
      'https://registry.npmjs.org/-/v1/search?text=rossoctl&size=10']
for u in urls:
    try:
        r=urllib.request.urlopen(u,timeout=15); j=json.load(r)
        for o in j.get('objects',[]): print(o['package']['name'], o['package'].get('description'))
    except Exception as e: print('ERR',repr(e)[:200])
PY

